import { test, expect, Page } from '@playwright/test';

test.describe('Internet Connection Drop - Friendly Error Message', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000');
  });

  test('should display friendly message when connection drops', async () => {
    // Simulate offline mode
    await page.context().setOffline(true);

    // Wait for error message to appear
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible({ timeout: 5000 });

    // Verify the message is friendly and informative
    await expect(errorMessage).toContainText(/connection|offline|internet/i);
  });

  test('should show retry button in offline message', async () => {
    // Go offline
    await page.context().setOffline(true);

    // Check for error message
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible({ timeout: 5000 });

    // Verify retry button exists
    const retryButton = page.getByRole('button', { name: /retry|reconnect/i });
    await expect(retryButton).toBeVisible();
  });

  test('should recover when connection is restored', async () => {
    // Go offline
    await page.context().setOffline(true);

    // Verify error message appears
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible({ timeout: 5000 });

    // Restore connection
    await page.context().setOffline(false);

    // Error message should disappear
    await expect(errorMessage).not.toBeVisible({ timeout: 5000 });
  });

  test('should display user-friendly error text', async () => {
    // Go offline
    await page.context().setOffline(true);

    // Get the alert message
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible({ timeout: 5000 });

    // Verify message contains friendly language (not technical jargon)
    const messageText = await errorMessage.textContent();
    expect(messageText).toBeTruthy();
    expect(messageText?.toLowerCase()).toMatch(/connection|offline|internet|unable to connect/i);
    expect(messageText).not.toMatch(/ERR_|ECONNREFUSED|socket/);
  });

  test('should allow user to retry connection', async () => {
    // Go offline
    await page.context().setOffline(true);

    // Wait for error message
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible({ timeout: 5000 });

    // Click retry button
    const retryButton = page.getByRole('button', { name: /retry|reconnect/i });
    await retryButton.click();

    // Restore connection to simulate successful retry
    await page.context().setOffline(false);

    // Error message should disappear after successful retry
    await expect(errorMessage).not.toBeVisible({ timeout: 5000 });
  });
});
